subrange_helper(int max,
                     const container& cont,
                     std::string_view what = "sizeof_stream_items")
{
    if (max == io_signature::IO_INFINITE) {
        return cont.end();
    }
    if (max < 0) {
        throw std::invalid_argument(fmt::format("Negative maximum count {:d}", max));
    }
    if (static_cast<size_t>(max) < cont.size()) {
        return cont.begin() + max;
    }
    return cont.end();
}

correlate_access_code_ff_ts_impl::set_access_code(const std::string& access_code)
{
    d_len = access_code.length(); // # of bytes in string
    if (d_len > 64)
        return false;

    // set len least significant bits to 1.
    d_mask = ((~0ULL) >> (64 - d_len));

    d_access_code = 0;
    for (unsigned i = 0; i < d_len; i++) {
        d_access_code = (d_access_code << 1) | (access_code[i] & 1);
    }

    d_logger->debug("Access code: {:x}", d_access_code);
    d_logger->debug("Mask: {:x}", d_mask);

    return true;
}

