dvbt2_pilotgenerator_cc_impl::init_prbs(void)
{
    int sr = 0x7ff;
    int j = 0;

    for (int i = 0; i < MAX_CARRIERS; i++) {
        int b = ((sr) ^ (sr >> 2)) & 1;
        prbs[i] = sr & 1;
        sr >>= 1;
        if (b) {
            sr |= 0x400;
        }
    }

    for (int i = 0; i < (CHIPS / 8); i++) {
        for (int k = 7; k >= 0; k--) {
            pn_sequence[j] = (pn_sequence_table[i] >> k) & 0x1;
            j = j + 1;
        }
    }
}

