buffer_reader_sm::items_available() const
{
    int available = 0;

    if ((nitems_read() - sample_delay()) != d_buffer->nitems_written()) {
        if (d_buffer->d_write_index == d_read_index) {
            if ((nitems_read() - sample_delay()) !=
                (d_buffer->nitems_written() + link()->history() - 1)) {
                available = d_buffer->d_bufsize - d_read_index;
            }
        } else {
            available = d_buffer->index_sub(d_buffer->d_write_index, d_read_index);
        }
    }

#ifdef BUFFER_DEBUG
    d_logger->debug("[{};{}] items_available() WR_idx: {} -- WR items: {} -- RD_idx: {} "
                    "-- RD items: {} (-{}) -- available: {}",
                    d_buffer,
                    this,
                    d_buffer->d_write_index,
                    d_buffer->nitems_written(),
                    d_read_index,
                    nitems_read(),
                    d_attr_delay,
                    available);
#endif

    return available;
}

