hier_block2_detail::connect(basic_block_sptr block)
{
    std::stringstream msg;

    // Check if duplicate
    if (std::find(d_blocks.begin(), d_blocks.end(), block) != d_blocks.end()) {
        msg << "Block " << block << " already connected.";
        throw std::invalid_argument(msg.str());
    }

    // Check if has inputs or outputs
    if (block->input_signature()->max_streams() != 0 ||
        block->output_signature()->max_streams() != 0) {
        msg << "Block " << block << " must not have any input or output ports";
        throw std::invalid_argument(msg.str());
    }

    hier_block2_sptr hblock(cast_to_hier_block2_sptr(block));

    if (hblock && hblock.get() != d_owner) {
        d_debug_logger->debug("connect: block is hierarchical, setting parent to {:p}",
                              (void*)this);
        hblock->d_detail->set_parent(this->d_owner);
    }

    d_blocks.push_back(block);
}

swap_iq_impl::work(int noutput_items,
                       gr_vector_const_void_star& input_items,
                       gr_vector_void_star& output_items)
{
    // Constructor guarantees we'll have pairs.

    long i;
    long noi;

    switch (d_datatype) {
    case SWAPTYPE_FLOATCOMPLEX: {
        noi = noutput_items * 2; // Each complex is 2 floats
        const float* in_float = (const float*)input_items[0];
        float* out_float = (float*)output_items[0];

        for (i = 0; i < noi; i += 2) {
            *out_float++ = in_float[i + 1];
            *out_float++ = in_float[i];
        }
    } break;
    case SWAPTYPE_SHORTCOMPLEX: {
        noi = noutput_items;
        const int16_t* in_short = (const int16_t*)input_items[0];
        int16_t* out_short = (int16_t*)output_items[0];

        for (i = 0; i < noi; i += 2) {
            *out_short++ = in_short[i + 1];
            *out_short++ = in_short[i];
        }
    } break;
    case SWAPTYPE_BYTECOMPLEX: {
        noi = noutput_items;
        const char* in_byte = (const char*)input_items[0];
        char* out_byte = (char*)output_items[0];

        for (i = 0; i < noi; i += 2) {
            *out_byte++ = in_byte[i + 1];
            *out_byte++ = in_byte[i];
        }
    } break;
    default: {
        d_logger->error("Unknown data type.  Bytes not swapped.");
        return WORK_DONE;
    }
    }

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

