context:
catv_frame_sync_enc_bb_impl::general_work(int noutput_items,
                                              gr_vector_int& ninput_items,
                                              gr_vector_const_void_star& input_items,
                                              gr_vector_void_star& output_items)
{
    const unsigned char* in = (const unsigned char*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];
    int consumed = 0;
    int i = 0;
    unsigned char b;

    while (i < noutput_items) {
        if (signal_constellation == CATV_MOD_64QAM) {
            for (int j = 0; j < 60 * 128; j++) {
                b = *in++;
                consumed++;
                for (int n = 6; n >= 0; n--) {
                    out[i++] = b & (1 << n) ? 1 : 0;
                }
            }
            b = 0x75;
            for (int n = 6; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            b = 0x2c;
            for (int n = 6; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            b = 0x0d;
            for (int n = 6; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            b = 0x6c;
            for (int n = 6; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            b = control_word << 3;
            for (int n = 6; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            for (int n = 6; n >= 0; n--) {
                out[i++] = 0;
            }
        } else {
            for (int j = 0; j < 88 * 128; j++) {
                b = *in++;
                consumed++;
                for (int n = 6; n >= 0; n--) {
                    out[i++] = b & (1 << n) ? 1 : 0;
                }
            }
            b = 0x71;
            for (int n = 7; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            b = 0xe8;
            for (int n = 7; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            b = 0x4d;
            for (int n = 7; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            b = 0xd4;
            for (int n = 7; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
            b = control_word << 4;
            for (int n = 7; n >= 0; n--) {
                out[i++] = b & (1 << n) ? 1 : 0;
            }
        }
    }

    // Tell runtime system how many input items we consumed on
    // each input stream.
    consume_each(consumed);

    // Tell runtime system how many output items we produced.
    return noutput_items;
}

