        d_logger->error("Message with unknown key {}", pmt::car(msg));
    }
    auto new_interp = pmt::to_long(pmt::cdr(msg));
    if (new_interp < 0) {
        d_logger->error(
            "Trying to set interpolation to {}, but must be a positive integer.",
            new_interp);
