time_sink_c_impl::_test_trigger_slope(const gr_complex* in) const
{
    float x0, x1;
    if (d_trigger_channel % 2 == 0) {
        x0 = in[0].real();
        x1 = in[1].real();
    } else {
        x0 = in[0].imag();
        x1 = in[1].imag();
    }

    if (d_trigger_slope == TRIG_SLOPE_POS)
        return ((x0 <= d_trigger_level) && (x1 > d_trigger_level));
    else
        return ((x0 >= d_trigger_level) && (x1 < d_trigger_level));
}

