                msg << "Key " << p.first << " requires PRIVLVL: <= " << p.second.priv
                    << " to get, currently at: " << cur_priv;
                GR_LOG_ERROR(d_logger, msg.str());
            }
        }

        TMap& d_getcallbackmap;
        const priv_lvl_t& cur_priv;
        TKnobMap& outknobs;
    }

