crc_check_impl::msg_handler(const pmt::pmt_t& pmt_msg)
{
    std::vector<uint8_t> msg = pmt::u8vector_elements(pmt::cdr(pmt_msg));
    unsigned num_bytes = d_num_bits / 8;

    const auto size = msg.size();
    if (size <= d_header_bytes + num_bytes) {
        d_logger->warn(
            "PDU too short; dropping ({}<={})", size, d_header_bytes + num_bytes);
        return;
    }

    // Read CRC from message
    uint64_t msg_crc = 0;
    if (d_swap_endianness) {
        for (auto i = size - 1; i >= size - num_bytes; --i) {
            msg_crc <<= 8;
            msg_crc |= msg[i];
        }
    } else {
        for (auto i = size - num_bytes; i < size; ++i) {
            msg_crc <<= 8;
            msg_crc |= msg[i];
        }
    }

    const uint64_t crc_computed =
        d_crc.compute(&msg[d_header_bytes], size - d_header_bytes - num_bytes);

    const bool crc_ok = crc_computed == msg_crc;
    if (crc_ok) {
        d_logger->trace("CRC OK");
    } else {
        // a CRC message fail has more information than a pass, so log it for debugging
        d_logger->debug("CRC fail");
    }

    const auto out_size = d_discard_crc ? size - num_bytes : size;
    // avoid the costly string PMT'ing for every single message
    static auto ok_port = pmt::mp("ok");
    static auto fail_port = pmt::mp("fail");
    message_port_pub(crc_ok ? ok_port : fail_port,
                     pmt::cons(pmt::car(pmt_msg), pmt::init_u8vector(out_size, msg)));
}

