context:
dvbt2_interleaver_bb_impl::general_work(int noutput_items,
                                            gr_vector_int& ninput_items,
                                            gr_vector_const_void_star& input_items,
                                            gr_vector_void_star& output_items)
{
    const unsigned char* in = (const unsigned char*)input_items[0];
    unsigned char* out = (unsigned char*)output_items[0];
    int consumed = 0;
    int produced = 0;
    int rows, offset, index, packed;
    unsigned int pack;
    const int* mux;

    switch (signal_constellation) {
    case MOD_QPSK:
        for (int i = 0; i < noutput_items; i += packed_items) {
            rows = frame_size / 2;
            if (code_rate == C1_3 || code_rate == C2_5) {
                for (int k = 0; k < nbch; k++) {
                    tempu[k] = *in++;
                }
                for (int t = 0; t < q_val; t++) {
                    for (int s = 0; s < 360; s++) {
                        tempu[nbch + (360 * t) + s] = in[(q_val * s) + t];
                    }
                }
                in = in + (q_val * 360);
                index = 0;
                for (int j = 0; j < rows; j++) {
                    out[produced] = tempu[index++] << 1;
                    out[produced++] |= tempu[index++];
                    consumed += 2;
                }
            } else {
                for (int j = 0; j < rows; j++) {
                    out[produced] = in[consumed++] << 1;
                    out[produced++] |= in[consumed++];
                }
            }
        }
        break;

    case MOD_16QAM:
        if (code_rate == C3_5 && frame_size == FRAME_SIZE_NORMAL) {
            mux = &mux16_35[0];
        } else if (code_rate == C1_3 && frame_size == FRAME_SIZE_SHORT) {
            mux = &mux16_13[0];
        } else if (code_rate == C2_5 && frame_size == FRAME_SIZE_SHORT) {
            mux = &mux16_25[0];
        } else {
            mux = &mux16[0];
        }
        packed = frame_size / (mod * 2);
        for (int i = 0; i < noutput_items; i += packed_items) {
            index = 0;
            for (int d = 0; d < packed; d++) {
                pack = 0;
                for (int e = 0; e < (mod * 2); e++) {
                    offset = mux[e];
                    pack |= in[lookup_table[index++]] << (((mod * 2) - 1) - offset);
                }
                out[produced++] = pack >> 4;
                out[produced++] = pack & 0xf;
            }
            consumed += frame_size;
            in += frame_size;
        }
        break;

    case MOD_64QAM:
        if (code_rate == C3_5 && frame_size == FRAME_SIZE_NORMAL) {
            mux = &mux64_35[0];
        } else if (code_rate == C1_3 && frame_size == FRAME_SIZE_SHORT) {
            mux = &mux64_13[0];
        } else if (code_rate == C2_5 && frame_size == FRAME_SIZE_SHORT) {
            mux = &mux64_25[0];
        } else {
            mux = &mux64[0];
        }
        packed = frame_size / (mod * 2);
        for (int i = 0; i < noutput_items; i += packed_items) {
            index = 0;
            for (int d = 0; d < packed; d++) {
                pack = 0;
                for (int e = 0; e < (mod * 2); e++) {
                    offset = mux[e];
                    pack |= in[lookup_table[index++]] << (((mod * 2) - 1) - offset);
                }
                out[produced++] = pack >> 6;
                out[produced++] = pack & 0x3f;
            }
            consumed += frame_size;
            in += frame_size;
        }
        break;

    case MOD_256QAM:
        if (frame_size == FRAME_SIZE_NORMAL) {
            if (code_rate == C3_5) {
                mux = &mux256_35[0];
            } else if (code_rate == C2_3) {
                mux = &mux256_23[0];
            } else {
                mux = &mux256[0];
            }
            packed = frame_size / (mod * 2);
            for (int i = 0; i < noutput_items; i += packed_items) {
                index = 0;
                for (int d = 0; d < packed; d++) {
                    pack = 0;
                    for (int e = 0; e < (mod * 2); e++) {
                        offset = mux[e];
                        pack |= in[lookup_table[index++]] << (((mod * 2) - 1) - offset);
                    }
                    out[produced++] = pack >> 8;
                    out[produced++] = pack & 0xff;
                }
                consumed += frame_size;
                in += frame_size;
            }
        }

        else { // frame_size = FRAME_SIZE_SHORT
            if (code_rate == C1_3) {
                mux = &mux256s_13[0];
            } else if (code_rate == C2_5) {
                mux = &mux256s_25[0];
            } else {
                mux = &mux256s[0];
            }
            packed = frame_size / mod;
            for (int i = 0; i < noutput_items; i += packed_items) {
                index = 0;
                for (int d = 0; d < packed; d++) {
                    pack = 0;
                    for (int e = 0; e < mod; e++) {
                        offset = mux[e];
                        pack |= in[lookup_table[index++]] << ((mod - 1) - offset);
                    }
                    out[produced++] = pack & 0xff;
                }
