                        for (int n = 0; n < N_TR; n++) {
                            vtemp =
                                (-2.0 * GR_M_PI * m * ((papr_map[n] + shift) - center)) /
                                papr_fft_size;
                            ctemp[n] = std::exp(gr_complexd(0.0, vtemp));
                        }
