    example_paths = []
    for file_dir in os.scandir(ROOT):
        # If it is a module
        if (
            path.isdir(file_dir) and
            file_dir.name.startswith("gr-") and not
            file_dir.name.startswith('gr-trellis')
        ):
            try:
                for pos_ex in os.scandir(path.join(file_dir, "examples")):
