codec2_decode_ps_impl::pack_frame(const unsigned char* in_unpacked,
                                       unsigned char* out_packed)
{
    memset((void*)&d_frame_buf[0], 0x00, d_bytes_per_frame);

    int byte_idx = 0, bit_idx = 0;
    for (int k = 0; k < d_bits_per_frame; k++) {
        out_packed[byte_idx] |= ((in_unpacked[k] & 0x01) << (7 - bit_idx));
        bit_idx = (bit_idx + 1) % 8;
        if (bit_idx == 0) {
            byte_idx++;
        }
    }
}

fmdet_cf_impl::work(int noutput_items,
                        gr_vector_const_void_star& input_items,
                        gr_vector_void_star& output_items)
{
    const gr_complex* iptr = (const gr_complex*)input_items[0];
    float* optr = (float*)output_items[0];

    int size = noutput_items;

    gr_complex Sdot, S0;
    gr_complex S1 = d_S1, S2 = d_S2, S3 = d_S3, S4 = d_S4;

    while (size-- > 0) {
        S0 = *iptr++;

        Sdot = d_scl * (-S0 + 8.f * S1 - 8.f * S3 + S4);

        d_freq = (S2.real() * Sdot.imag() - S2.imag() * Sdot.real()) /
                 (S2.real() * S2.real() + S2.imag() * S2.imag());

        S4 = S3;
        S3 = S2;
        S2 = S1;
        S1 = S0;

        *optr++ = d_freq - d_bias;
    }
    d_S1 = S1;
    d_S2 = S2;
    d_S3 = S3;
    d_S4 = S4;
    return noutput_items;
}

