windows_sink::write_waveout(LPWAVEHDR lp_wave_hdr)
{
    UINT w_result;

    /* Clear the WHDR_DONE bit (which the driver set last time that
    this WAVEHDR was sent via waveOutWrite and was played). Some
    drivers need this to be cleared */
    lp_wave_hdr->dwFlags = 0L;

    w_result = waveOutPrepareHeader(d_h_waveout, lp_wave_hdr, sizeof(WAVEHDR));
    if (w_result != 0) {
        d_logger->error("Failed to waveOutPrepareHeader {:s}", strerror(errno));
        return -1;
    }

    w_result = waveOutWrite(d_h_waveout, lp_wave_hdr, sizeof(WAVEHDR));
    if (w_result != 0) {
        d_logger->error("Failed to write block to device {:s}", strerror(errno));
        switch (w_result) {
        case MMSYSERR_INVALHANDLE:
            d_logger->error("Specified device handle is invalid");
            break;
        case MMSYSERR_NODRIVER:
            d_logger->error("No device driver is present");
            break;
        case MMSYSERR_NOMEM:
            d_logger->error("Unable to allocate or lock memory");
            break;
        case WAVERR_UNPREPARED:
            d_logger->error("The data block pointed to by the pwh parameter hasn't "
                            "been prepared.");
            break;
        default:
            d_logger->error("Unknown error {:d}", w_result);
        }
        waveOutUnprepareHeader(d_h_waveout, lp_wave_hdr, sizeof(WAVEHDR));
        return -1;
    }
    return 0;
}

