def fir_filter(x, taps):
    y = []
    x2 = (len(taps) - 1) * [0, ] + x
    delay = (len(taps) - 1) // 2
    for i in range(len(x)):
        yi = 0
        for j in range(len(taps)):
            yi += taps[len(taps) - 1 - j] * x2[i + j]
        y.append(complex(x2[i + delay], yi))
    return y

