context:
file_descriptor_source_impl::work(int noutput_items,
                                      gr_vector_const_void_star& input_items,
                                      gr_vector_void_star& output_items)
{
    assert(noutput_items > 0);

    char* o = (char*)output_items[0];
    int nread = 0;

    while (1) {
        int r = read_items(o, noutput_items - nread);
        if (r == -1) {
            if (errno == EINTR)
                continue;
            else {
                d_logger->error("[read]: {:s}", strerror(errno));
                return -1;
            }
        } else if (r == 0) { // end of file
            if (!d_repeat)
                break;
            else {
                flush_residue();
                if (lseek(d_fd, 0, SEEK_SET) == -1) {
                    d_logger->error("[lseek]: {:s}", strerror(errno));
                    return -1;
                }
            }
        } else {
            o += r * d_itemsize;
            nread += r;
            break;
        }
    }

    if (nread == 0) // EOF
        return -1;

    return nread;
}

cc_decoder_impl::chainback_viterbi(unsigned char* data,
                                       unsigned int nbits,
                                       unsigned int endstate,
                                       unsigned int tailsize)
{
    /* ADDSHIFT and SUBSHIFT make sure that the thing returned is a byte. */
    unsigned char* d = d_vp.decisions.data();
    /* Make room beyond the end of the encoder register so we can
     * accumulate a full byte of decoded data
     */

    endstate = (endstate % s_numstates) << s_ADDSHIFT;

    /* The store into data[] only needs to be done every 8 bits.
     * But this avoids a conditional branch, and the writes will
     * combine in the cache anyway
     */

    d += tailsize * s_decision_t_size; /* Look past tail */
    int retval;
    int dif = tailsize - (s_k - 1);
    decision_t dec;
    while (nbits-- > d_frame_size - (s_k - 1)) {
        int k;
        dec.t = &d[nbits * s_decision_t_size];
        k = (dec.w[(endstate >> s_ADDSHIFT) / 32] >> ((endstate >> s_ADDSHIFT) % 32)) & 1;

        endstate = (endstate >> 1) | (k << (s_k - 2 + s_ADDSHIFT));
        data[((nbits + dif) % d_frame_size)] = k;

        retval = endstate;
    }
    nbits += 1;

    while (nbits-- != 0) {
        int k;

        dec.t = &d[nbits * s_decision_t_size];

        k = (dec.w[(endstate >> s_ADDSHIFT) / 32] >> ((endstate >> s_ADDSHIFT) % 32)) & 1;

        endstate = (endstate >> 1) | (k << (s_k - 2 + s_ADDSHIFT));
        data[((nbits + dif) % d_frame_size)] = k;
    }

    return retval >> s_ADDSHIFT;
}

usrp_block_impl::_check_mboard_sensors_locked()
{
    bool clocks_locked = true;

    // Check ref lock for all mboards
    for (size_t mboard_index = 0; mboard_index < _dev->get_num_mboards();
         mboard_index++) {
        std::string sensor_name = "ref_locked";
        if (_dev->get_clock_source(mboard_index) == "internal") {
            continue;
        } else if (_dev->get_clock_source(mboard_index) == "mimo") {
            sensor_name = "mimo_locked";
        }
        if (not _wait_for_locked_sensor(get_mboard_sensor_names(mboard_index),
                                        sensor_name,
