pack_output(unsigned code, int bits)
{
    static unsigned int out_buffer = 0;
    static int out_bits = 0;
    unsigned char out_byte;

    out_buffer |= (code << out_bits);
    out_bits += bits;
    if (out_bits >= 8) {
        out_byte = out_buffer & 0xff;
        out_bits -= 8;
        out_buffer >>= 8;
        fwrite(&out_byte, sizeof(char), 1, stdout);
    }
    return (out_bits > 0);
}

