basic_vco(float* output, const float* input)
{
    double phase = 0;

    for (auto j = iterations / block_size; j; --j) {
        for (uint64_t i = 0; i < block_size; i++) {
            output[i] = cos(phase) * amplitude;
            phase += input[i] * k;

            while (phase > 2 * GR_M_PI)
                phase -= 2 * GR_M_PI;

            while (phase < -2 * GR_M_PI)
                phase += 2 * GR_M_PI;
        }
    }
}

