context:
wavfile_sink_impl::work(int noutput_items,
                            gr_vector_const_void_star& input_items,
                            gr_vector_void_star& output_items)
{
    auto in = (const float**)&input_items[0];
    int n_in_chans = input_items.size();
    int nwritten;
    int errnum;

    gr::thread::scoped_lock guard(d_mutex); // hold mutex for duration of this block
    do_update();                            // update: d_fp is read
    if (!d_fp) {                            // drop output on the floor
        return noutput_items;
    }

    int nchans = d_h.nchans;
    for (nwritten = 0; nwritten < noutput_items; nwritten++) {
        for (int chan = 0; chan < nchans; chan++) {
            // Write zeros to channels which are in the WAV file
            // but don't have any inputs here
            if (chan < n_in_chans) {
                d_buffer[chan + (nwritten * nchans)] = in[chan][nwritten];
            } else {
                d_buffer[chan + (nwritten * nchans)] = 0;
            }
        }
    }

    sf_write_float(d_fp, &d_buffer[0], nchans * nwritten);

    errnum = sf_error(d_fp);
    if (errnum) {
        d_logger->error("sf_error: {:s}", sf_error_number(errnum));
        close();
        throw std::runtime_error("File I/O error.");
    }

    return nwritten;
}

header_format_default::format(int nbytes_in,
                                   const unsigned char* input,
                                   pmt::pmt_t& output,
                                   pmt::pmt_t& info)
{
    // Creating the output pmt copies data; free our own here when done.
    volk::vector<uint8_t> bytes_out(header_nbytes());

    header_buffer header(bytes_out.data());
    header.add_field64(d_access_code, d_access_code_len);
    header.add_field16((uint16_t)(nbytes_in));
    header.add_field16((uint16_t)(nbytes_in));

    // Package output data into a PMT vector
    output = pmt::init_u8vector(header_nbytes(), bytes_out.data());

    return true;
}

handle_ctrl_msg(pmt::pmt_t ctrl_msg)
{
    // if we do not receive a dictionary, don't do anything:
    if (!pmt::is_dict(ctrl_msg))
        return;

    // check dict for EOB offset command
    if (pmt::dict_has_key(ctrl_msg, eob_offset())) {
        uint32_t new_eob_offset = pmt::to_uint64(
            pmt::dict_ref(ctrl_msg, eob_offset(), pmt::from_uint64(d_eob_offset)));
        set_eob_parameters(d_eob_alignment, new_eob_offset);
        this->d_logger->notice("command received - set EOB tag offset to {:d} symbols",
                               d_eob_offset);
    }

    // check dict for EOB alignment command
    if (pmt::dict_has_key(ctrl_msg, eob_alignment())) {
        uint32_t new_eob_alignment = pmt::to_uint64(
            pmt::dict_ref(ctrl_msg, eob_alignment(), pmt::from_uint64(d_eob_alignment)));
        if (new_eob_alignment > 0) {
            set_eob_parameters(new_eob_alignment, d_eob_offset);
            this->d_logger->notice(
                "command received - set EOB tag alignment to {:d} symbols",
                d_eob_alignment);
        } else {
            this->d_logger->error("command received - illegal value {:d} for EOB "
                                  "alignment, not setting",
                                  new_eob_alignment);
        }
    }

    // handle other control messages...
}

def handle_msg(self, pdu):
        if self.metadict_mode == "META":
            meta = pmt.car(pdu)
            try:
                val = pmt.to_python(pmt.dict_ref(meta, self.key, pmt.PMT_NIL))
                if val:
                    val = self.fn(val)
                meta = pmt.dict_add(meta, self.key, pmt.to_pmt(val))
            except Exception as e:
                print(e)
                pass
            self.message_port_pub(pmt.intern("pdu"),
                                  pmt.cons(meta, pmt.cdr(pdu)))

        elif self.metadict_mode == "UVEC":
            vec = pmt.cdr(pdu)
            try:
                vec = pmt.to_pmt(self.fn(pmt.to_python(vec)))
            except Exception as e:
                print(e)
                pass

            self.message_port_pub(pmt.intern("pdu"),
                                  pmt.cons(pmt.car(pdu), vec))

        elif self.metadict_mode == "RAW":
            # TODO: This is more of a "message lambda" block, in the future it should be
            # a separate block outside the PDU namespace
            try:
                pdu = self.fn(pdu)
            except Exception as e:
                print(e)
                pass
            self.message_port_pub(pmt.intern("pdu"), pdu)

        else:
            raise ValueError(
                "pdu_lambda block instantiated in unknown mode " + repr(self.metadict_mode))
            pass

