catv_trellis_enc_bb_impl::diff_precoder(unsigned char W,
                                             unsigned char Z,
                                             unsigned char* Xp,
                                             unsigned char* Yp)
{
    unsigned char common, newX, newY;

    common = (Z & (*Xp ^ *Yp));
    newX = W ^ *Xp ^ common;
    newY = Z ^ W ^ *Yp ^ common;

    *Xp = newX;
    *Yp = newY;
}

