file_source_impl::seek(int64_t seek_point, int whence)
{
    if (d_seekable) {
        seek_point += d_start_offset_items;

        switch (whence) {
        case SEEK_SET:
            break;
        case SEEK_CUR:
            seek_point += (d_length_items - d_items_remaining);
            break;
        case SEEK_END:
            seek_point = d_length_items - seek_point;
            break;
        default:
            d_logger->warn("bad seek mode {:d}", whence);
            return 0;
        }

        if ((seek_point < (int64_t)d_start_offset_items) ||
            (seek_point > (int64_t)(d_start_offset_items + d_length_items - 1))) {
            d_logger->warn("bad seek point {:d}", seek_point);
            return 0;
        }
        d_items_remaining = d_length_items - (seek_point - d_start_offset_items);
        return GR_FSEEK((FILE*)d_fp, seek_point * d_itemsize, SEEK_SET) == 0;
    } else {
        d_logger->warn("file not seekable");
        return 0;
    }
}

work(int noutput_items,
                                gr_vector_const_void_star& input_items,
                                gr_vector_void_star& output_items)
{
    T* optr = (T*)output_items[0];

    if (d_repeat) {
        unsigned int size = d_data.size();
        unsigned int offset = d_offset;
        if (size == 0)
            return -1;

        if (d_settags) {
            int n_outputitems_per_vector = d_data.size() / d_vlen;
            for (int i = 0; i < noutput_items; i += n_outputitems_per_vector) {
                // FIXME do proper vector copy
                memcpy((void*)optr, (const void*)&d_data[0], size * sizeof(T));
                optr += size;
                for (unsigned t = 0; t < d_tags.size(); t++) {
                    this->add_item_tag(0,
                                       this->nitems_written(0) + i + d_tags[t].offset,
                                       d_tags[t].key,
                                       d_tags[t].value,
                                       d_tags[t].srcid);
                }
            }
        } else {
            for (int i = 0; i < static_cast<int>(noutput_items * d_vlen); i++) {
                optr[i] = d_data[offset++];
                if (offset >= size) {
                    offset = 0;
                }
            }
        }

        d_offset = offset;
        return noutput_items;
    } else {
        if (d_offset >= d_data.size())
            return -1; // Done!

        unsigned n = std::min((unsigned)d_data.size() - d_offset,
                              (unsigned)noutput_items * d_vlen);
        for (unsigned i = 0; i < n; i++) {
            optr[i] = d_data[d_offset + i];
        }
        for (unsigned t = 0; t < d_tags.size(); t++) {
            if ((d_tags[t].offset >= d_offset) && (d_tags[t].offset < d_offset + n))
                this->add_item_tag(
                    0, d_tags[t].offset, d_tags[t].key, d_tags[t].value, d_tags[t].srcid);
        }
        d_offset += n;
        return n / d_vlen;
    }
}

