def make_active_scm_manager(self):
        """ Returns a valid, usable object of type SCMRepository. """
        if self.options.scm_mode == 'no':
            return SCMRepository(self.path_to_repo)
        for glbl in list(globals().values()):
            try:
                if issubclass(glbl, SCMRepository):
                    the_scm = glbl(self.path_to_repo)
                    if the_scm.is_active():
                        logger.info(
                            f"Found SCM of type: {the_scm.handles_scm_type}")
                        return the_scm
            except (TypeError, AttributeError, InvalidSCMError):
                pass
        if self.options == 'yes':
            return None
        return SCMRepository(self.path_to_repo)

polar_common::initialize_info_bit_position_vector()
{
    int num_frozen_bit = 0;
    int frozen_pos = d_frozen_bit_positions.at(num_frozen_bit);
    for (int i = 0; i < d_block_size; i++) {
        if (i != frozen_pos) {
            d_info_bit_positions.push_back((int)i);
        } else {
            num_frozen_bit++;
            num_frozen_bit =
                std::min(num_frozen_bit, (int)(d_frozen_bit_positions.size() - 1));
            frozen_pos = d_frozen_bit_positions.at(num_frozen_bit);
        }
    }

    if ((int)d_info_bit_positions.size() != num_info_bits()) {
        throw std::runtime_error(
            "polar_common: number of info bit positions MUST equal num_info_bits (K)!");
    }
}

