catv_reed_solomon_enc_bb_impl::init_rs()
{
    unsigned char x;
    int i, j;

    gf_exp[0] = 1;
    gf_log[1] = 0;

    x = 1;
    for (i = 1; i < 127; i++) {
        x <<= 1;
        if (x & 0x80) {
            x = (x & 0x7F) ^ 0x09;
        }
        gf_exp[i] = x;
        gf_log[x] = i;
    }
    for (; i < 256; i++) {
        gf_exp[i] = gf_exp[i - 127];
    }

    for (i = 0; i < 128; i++) {
        for (j = 0; j < 128; j++) {
            if ((i == 0) || (j == 0)) {
                gf_mul_table[i][j] = 0;
            } else {
                gf_mul_table[i][j] = gf_exp[gf_log[i] + gf_log[j]];
            }
        }
    }
}

