conv_bit_corr_bb_impl::data_garble_rate(int taps, float target)
{
    double base, expo, answer;

    if (target > 0.5)
        target = 1 - target;

    base = 1.0 - 2.0 * target;
    expo = (double)1 / taps;
    answer = 0.5 * (1 - pow(base, expo));

    if ((errno == EDOM) || (errno == ERANGE)) {
        d_logger->error("Out of range errors while computing garble rate.");
        throw std::runtime_error("conv_bit_corr_bb_impl::data_garble_rate");
    }
    return answer;
}

