GF2Mat::get_G(std::vector<int>& permute, int& rank)
{
    permute.resize(N);
    rank = 0;
    for (int col = 0; col < N; col++) {
        permute[col] = col;
    }
    GF2Mat G(H);
    int diag = 0;
    int limit = M;
    int temp;
    while (diag < limit) {
        bool non_zero = false;
        for (int col = diag; col < N; col++) {
            if (G.get_element(diag, col) == char(1)) {
                non_zero = true;
                rank++;
                G.swap_cols(diag, col);
                temp = permute[diag];
                permute[diag] = permute[col];
                permute[col] = temp;
                break;
            }
        }
        if (non_zero) {
            for (int row = 0; row < diag; row++) {
                if (G.get_element(row, diag) == char(1)) {
                    G.add_rows(row, diag);
                }
            }
            for (int row = diag + 1; row < M; row++) {
                if (G.get_element(row, diag) == char(1)) {
                    G.add_rows(row, diag);
                }
            }
            diag++;
        } else {
            GF2Vec current_row;
            current_row = G.get_row(diag);
            for (int row = diag; row < limit - 1; row++) {
                G.set_row(row, G.get_row(row + 1));
            }
            G.set_row(limit - 1, current_row);
            limit--;
        }
    }
    return G;
}

