dvbt2_framemapper_cc_impl::add_crc32_bits(unsigned char* in, int length)
{
    unsigned int crc = 0xffffffff;
    int b;
    int i = 0;

    for (int n = 0; n < length; n++) {
        b = in[i++] ^ ((crc >> 31) & 0x01);
        crc <<= 1;
        if (b) {
            crc ^= CRC_POLY;
        }
    }

    for (int n = 31; n >= 0; n--) {
        in[i++] = (crc & (1 << n)) ? 1 : 0;
    }
    return 32;
}

