def design_opt_hb(fs, gain, mainwin):
    ret = True
    filtord, r = getfloat(mainwin.gui.firhbordEdit.text())
    ret = r and ret
    trwidth, r = getfloat(mainwin.gui.firhbtrEdit.text())
    ret = r and ret
    if int(filtord) & 1:
        reply = QtWidgets.QMessageBox.information(mainwin, "Filter order should be even",
                                                  "Filter order should be even", QtWidgets.QMessageBox.Ok)
        return ([], [], False)

    if(ret):
        try:
            bands = [0, .25 - (trwidth / fs), .25 + (trwidth / fs), 0.5]
            taps = scipy.signal.remez(int(filtord) + 1, bands, [1, 0], [1, 1])
            taps[abs(taps) <= 1e-6] = 0.
        except RuntimeError as e:
            reply = QtWidgets.QMessageBox.information(mainwin, "Filter Design Error",
                                                      e.args[0], QtWidgets.QMessageBox.Ok)
            return ([], [], False)
        else:
            params = {"fs": fs, "gain": gain, "wintype": mainwin.EQUIRIPPLE_FILT,
                      "filttype": "hb", "ntaps": len(taps)}
            return (taps, params, ret)
    else:
        return ([], [], ret)

fsm::fsm(const char* name)
{
    FILE* fsmfile;

    if ((fsmfile = fopen(name, "r")) == NULL)
        throw std::runtime_error("fsm::fsm(const char *name): file open error");
    // printf("file open error in fsm()\n");

    if (fscanf(fsmfile, "%d %d %d\n", &d_I, &d_S, &d_O) == EOF) {
        if (ferror(fsmfile) != 0)
            throw std::runtime_error("fsm::fsm(const char *name): file read error");
    }

    d_NS.resize(d_I * d_S);
    d_OS.resize(d_I * d_S);

    for (int i = 0; i < d_S; i++) {
        for (int j = 0; j < d_I; j++) {
            if (fscanf(fsmfile, "%d", &(d_NS[i * d_I + j])) == EOF) {
                if (ferror(fsmfile) != 0)
                    throw std::runtime_error(
                        "fsm::fsm(const char *name): file read error");
            }
        }
    }
    for (int i = 0; i < d_S; i++) {
        for (int j = 0; j < d_I; j++) {
            if (fscanf(fsmfile, "%d", &(d_OS[i * d_I + j])) == EOF) {
                if (ferror(fsmfile) != 0)
                    throw std::runtime_error(
                        "fsm::fsm(const char *name): file read error");
            }
        }
    }

    fclose(fsmfile);

    generate_PS_PI();
    generate_TM();
}

