constellation_psk::get_sector(const gr_complex* sample)
{
    float phase = arg(*sample);
    float width = (2.0 * GR_M_PI) / n_sectors;
    int sector = floor(phase / width + 0.5);
    if (sector < 0)
        sector += n_sectors;
    return sector;
}

